import '../models/models.dart';

class AnnualPhysicsUnit {
  final SchoolLevel level;
  final String code, title, lessonId, lessonTitle, summary, content;
  final int unitOrder;
  final List<String> keyPoints;
  final List<Exercise> exercises;
  const AnnualPhysicsUnit({
    required this.level, required this.code, required this.unitOrder,
    required this.title, required this.lessonId, required this.lessonTitle,
    required this.summary, required this.content, required this.keyPoints,
    required this.exercises,
  });
  String get subjectId => code == 'troisieme' ? 'trois_pc' : 'core_pct_$code';
  String get chapterId => 'core_pct_${code}_unit_${unitOrder}';
}

const annualPhysicsUnits = <AnnualPhysicsUnit>[
  AnnualPhysicsUnit(level:SchoolLevel.sixieme,code:'sixieme',unitOrder:1,title:'Volume et masse',lessonId:'core_pct_6e_volume_mass',lessonTitle:'Mesurer le volume et la masse',summary:'Mesurer le volume d’un liquide et la masse d’un objet avec une unité adaptée.',content:'Un solide conserve sa forme, tandis qu’un liquide prend la forme du récipient. Le volume indique l’espace occupé et se mesure en mL, L ou cm³. La masse se mesure avec une balance en g ou kg. La capacité d’un récipient indique le volume de liquide qu’il peut contenir. Pour mesurer, lis le niveau à hauteur des yeux et note toujours l’unité.',keyPoints:['Volume : L, mL ou cm³','Masse : g ou kg','Capacité = volume maximal contenu'],exercises:[
    Exercise(id:'core_pct_6e_vm1',lessonId:'core_pct_6e_volume_mass',question:'Quel instrument sert à mesurer la masse ?',options:['Une balance','Un thermomètre','Une règle'],correctIndex:0,explanation:'La balance mesure la masse.'),
    Exercise(id:'core_pct_6e_vm2',lessonId:'core_pct_6e_volume_mass',question:'Quelle unité convient à la capacité d’une bouteille ?',options:['Litre','Kilogramme','Mètre'],correctIndex:0,explanation:'La capacité d’un récipient peut se mesurer en litres.'),
    Exercise(id:'core_pct_6e_vm3',lessonId:'core_pct_6e_volume_mass',question:'1 L correspond à…',options:['100 mL','1 000 mL','10 mL'],correctIndex:1,explanation:'Un litre vaut 1 000 millilitres.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.sixieme,code:"sixieme",unitOrder:2,title:'États de l’eau et température',lessonId:'core_pct_6e_water_states',lessonTitle:'Les changements d’état de l’eau',summary:'Identifier les trois états de l’eau et leurs changements.',content:'L’eau existe sous forme solide (glace), liquide (eau) et gazeuse (vapeur d’eau). La fusion fait passer du solide au liquide ; la solidification du liquide au solide ; la vaporisation du liquide au gaz ; la condensation du gaz au liquide. La température se lit avec un thermomètre. La chaleur est un transfert d’énergie, tandis que la température indique l’état thermique.',keyPoints:['Glace : solide ; eau : liquide ; vapeur : gaz','Fusion : solide vers liquide','Vaporisation : liquide vers gaz','Température et chaleur sont différentes'],exercises:[
    Exercise(id:'core_pct_6e_ws1',lessonId:'core_pct_6e_water_states',question:'Le passage de la glace à l’eau liquide s’appelle…',options:['Fusion','Condensation','Solidification'],correctIndex:0,explanation:'La fusion transforme un solide en liquide.'),
    Exercise(id:'core_pct_6e_ws2',lessonId:'core_pct_6e_water_states',question:'Quel instrument mesure la température ?',options:['Thermomètre','Balance','Éprouvette'],correctIndex:0,explanation:'Le thermomètre sert à mesurer la température.'),
    Exercise(id:'core_pct_6e_ws3',lessonId:'core_pct_6e_water_states',question:'La condensation transforme…',options:['Un gaz en liquide','Un liquide en solide','Un solide en gaz'],correctIndex:0,explanation:'La condensation est le passage du gaz au liquide.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.sixieme,code:"sixieme",unitOrder:3,title:'Circuit électrique simple',lessonId:'core_pct_6e_circuit',lessonTitle:'Réaliser et sécuriser un circuit simple',summary:'Identifier générateur, récepteur, conducteur et isolant.',content:'Un circuit simple comprend une source d’énergie (pile), des fils et un récepteur (lampe). Le circuit doit être fermé pour que la lampe s’allume. Les métaux conduisent généralement le courant ; le plastique et le bois sec sont des isolants. N’utilise jamais une prise de secteur pour une expérience scolaire : travaille uniquement avec des piles basse tension et sous la supervision de l’enseignant.',keyPoints:['Circuit fermé : la lampe peut s’allumer','Métal : conducteur ; plastique : isolant','Ne jamais expérimenter sur une prise secteur'],exercises:[
    Exercise(id:'core_pct_6e_ci1',lessonId:'core_pct_6e_circuit',question:'Quand une lampe d’un circuit simple s’allume-t-elle ?',options:['Quand le circuit est fermé','Quand le fil est coupé','Quand la pile est retirée'],correctIndex:0,explanation:'Le courant circule dans un circuit fermé.'),
    Exercise(id:'core_pct_6e_ci2',lessonId:'core_pct_6e_circuit',question:'Quel matériau est généralement isolant ?',options:['Plastique','Cuivre','Fer'],correctIndex:0,explanation:'Le plastique est un isolant électrique.'),
    Exercise(id:'core_pct_6e_ci3',lessonId:'core_pct_6e_circuit',question:'Quelle règle est essentielle ?',options:['Ne jamais utiliser une prise secteur en expérience','Toucher les fils nus','Court-circuiter la pile'],correctIndex:0,explanation:'Les expériences scolaires doivent utiliser une basse tension et respecter la sécurité.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.cinquieme,code:"cinquieme",unitOrder:1,title:'Gaz et pression',lessonId:'core_pct_5e_gas_pressure',lessonTitle:'Comprendre l’état gazeux et la pression',summary:'Décrire les propriétés d’un gaz et la pression atmosphérique.',content:'Un gaz occupe tout l’espace disponible dans un récipient et peut être comprimé. La pression mesure l’action d’un gaz sur une surface. L’air exerce une pression appelée pression atmosphérique. On peut mesurer une pression avec un manomètre ou un baromètre selon le contexte. La masse volumique relie la masse au volume : ρ = m/V.',keyPoints:['Un gaz est compressible','L’air exerce une pression','Masse volumique : ρ = m/V'],exercises:[
    Exercise(id:'core_pct_5e_gp1',lessonId:'core_pct_5e_gas_pressure',question:'Quelle propriété caractérise un gaz ?',options:['Il est compressible','Il garde toujours sa forme','Il ne remplit pas le récipient'],correctIndex:0,explanation:'Un gaz peut être comprimé et occupe le volume disponible.'),
    Exercise(id:'core_pct_5e_gp2',lessonId:'core_pct_5e_gas_pressure',question:'Quelle relation donne la masse volumique ?',options:['ρ = m/V','ρ = V/m','ρ = m + V'],correctIndex:0,explanation:'La masse volumique est la masse divisée par le volume.'),
    Exercise(id:'core_pct_5e_gp3',lessonId:'core_pct_5e_gas_pressure',question:'L’air autour de nous exerce…',options:['Une pression atmosphérique','Aucune pression','Seulement une masse nulle'],correctIndex:0,explanation:'L’atmosphère exerce une pression sur les objets.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.cinquieme,code:"cinquieme",unitOrder:2,title:'Dilatation et transfert de chaleur',lessonId:'core_pct_5e_heat',lessonTitle:'La chaleur et la dilatation',summary:'Expliquer la dilatation et les modes de transfert de chaleur.',content:'Quand la température augmente, de nombreux solides, liquides et gaz se dilatent : leur dimension ou leur volume augmente. La chaleur se transmet par conduction (surtout dans les solides), convection (mouvement d’un fluide) et rayonnement. Les isolants thermiques ralentissent le transfert de chaleur. Les ponts et rails comportent des espaces de dilatation.',keyPoints:['La dilatation accompagne souvent le chauffage','Conduction, convection, rayonnement','Les isolants ralentissent les transferts'],exercises:[
    Exercise(id:'core_pct_5e_ht1',lessonId:'core_pct_5e_heat',question:'Quel mode de transfert se fait par mouvement d’un liquide ou d’un gaz ?',options:['Convection','Conduction','Réflexion'],correctIndex:0,explanation:'La convection implique le déplacement d’un fluide.'),
    Exercise(id:'core_pct_5e_ht2',lessonId:'core_pct_5e_heat',question:'Pourquoi laisse-t-on des joints entre certains rails ?',options:['Pour permettre la dilatation','Pour augmenter leur masse','Pour les rendre transparents'],correctIndex:0,explanation:'Les matériaux peuvent se dilater quand leur température augmente.'),
    Exercise(id:'core_pct_5e_ht3',lessonId:'core_pct_5e_heat',question:'La chaleur du Soleil arrive principalement par…',options:['Rayonnement','Conduction dans l’air','Convection dans le vide'],correctIndex:0,explanation:'Le rayonnement peut se propager dans le vide.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.cinquieme,code:"cinquieme",unitOrder:3,title:'Courant électrique et matière',lessonId:'core_pct_5e_current_atoms',lessonTitle:'Mesurer le courant et découvrir les atomes',summary:'Lire des mesures électriques et introduire atomes, molécules et mélanges.',content:'L’intensité du courant se mesure avec un ampèremètre placé en série et s’exprime en ampères (A). La tension se mesure avec un voltmètre branché en dérivation et s’exprime en volts (V). La matière est constituée de particules : les molécules sont formées d’atomes. Un corps pur contient une seule espèce chimique ; un mélange en contient plusieurs.',keyPoints:['Ampèremètre en série : intensité (A)','Voltmètre en dérivation : tension (V)','Molécule = assemblage d’atomes'],exercises:[
    Exercise(id:'core_pct_5e_ca1',lessonId:'core_pct_5e_current_atoms',question:'Comment branche-t-on un ampèremètre ?',options:['En série','En dérivation','Sans circuit'],correctIndex:0,explanation:'L’ampèremètre se place en série pour mesurer l’intensité.'),
    Exercise(id:'core_pct_5e_ca2',lessonId:'core_pct_5e_current_atoms',question:'Une molécule est constituée…',options:['D’atomes','De cellules uniquement','De lumière'],correctIndex:0,explanation:'Une molécule est un assemblage d’atomes.'),
    Exercise(id:'core_pct_5e_ca3',lessonId:'core_pct_5e_current_atoms',question:'Un mélange contient…',options:['Plusieurs espèces chimiques','Toujours une seule espèce','Aucun corps'],correctIndex:0,explanation:'Un mélange associe plusieurs espèces chimiques.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.quatrieme,code:"quatrieme",unitOrder:1,title:'Poussée d’Archimède',lessonId:'core_pct_4e_archimedes',lessonTitle:'Comprendre la poussée d’Archimède',summary:'Expliquer pourquoi un objet immergé semble plus léger et quand il flotte.',content:'Un liquide exerce sur un corps immergé une force verticale dirigée vers le haut : la poussée d’Archimède. Elle dépend notamment du volume de fluide déplacé et de la masse volumique du fluide. Un objet flotte lorsque la poussée peut équilibrer son poids. On retrouve ce principe dans les bateaux et les bouées.',keyPoints:['La poussée est dirigée vers le haut','Elle dépend du fluide et du volume déplacé','Flottaison : équilibre entre poids et poussée'],exercises:[
    Exercise(id:'core_pct_4e_ar1',lessonId:'core_pct_4e_archimedes',question:'Dans quel sens agit la poussée d’Archimède ?',options:['Vers le haut','Vers le bas uniquement','Horizontalement uniquement'],correctIndex:0,explanation:'La poussée d’Archimède est verticale et dirigée vers le haut.'),
    Exercise(id:'core_pct_4e_ar2',lessonId:'core_pct_4e_archimedes',question:'Quel objet utilise le principe de flottaison ?',options:['Un bateau','Une craie sèche','Une règle posée sur une table'],correctIndex:0,explanation:'Le bateau flotte grâce à la poussée exercée par l’eau.'),
    Exercise(id:'core_pct_4e_ar3',lessonId:'core_pct_4e_archimedes',question:'La poussée dépend notamment…',options:['Du volume de fluide déplacé','De la couleur de l’objet','Du nom de l’objet'],correctIndex:0,explanation:'Le volume de fluide déplacé est un facteur important.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.quatrieme,code:"quatrieme",unitOrder:2,title:'Optique et ombres',lessonId:'core_pct_4e_optics',lessonTitle:'Propagation de la lumière et formation des ombres',summary:'Reconnaître les sources lumineuses, les récepteurs et les ombres.',content:'La lumière se propage en ligne droite dans un milieu homogène transparent. Une source primaire produit sa propre lumière ; un objet éclairé peut diffuser la lumière reçue. Un corps opaque bloque la lumière et forme une ombre. La taille de l’ombre varie avec la position de la source, de l’objet et de l’écran. Les éclipses sont liées aux ombres dans le système Soleil-Terre-Lune.',keyPoints:['La lumière se propage rectilignement','Corps opaque : bloque la lumière','Ombre : zone où la lumière n’arrive pas'],exercises:[
    Exercise(id:'core_pct_4e_op1',lessonId:'core_pct_4e_optics',question:'Quel objet est une source primaire de lumière ?',options:['Le Soleil','La Lune éclairée','Un cahier'],correctIndex:0,explanation:'Le Soleil produit sa propre lumière.'),
    Exercise(id:'core_pct_4e_op2',lessonId:'core_pct_4e_optics',question:'Quel matériau forme nettement une ombre ?',options:['Un corps opaque','Un verre transparent','L’air clair'],correctIndex:0,explanation:'Un corps opaque bloque la lumière.'),
    Exercise(id:'core_pct_4e_op3',lessonId:'core_pct_4e_optics',question:'La lumière dans un milieu homogène se propage…',options:['En ligne droite','En cercle obligatoire','Sans direction'],correctIndex:0,explanation:'On modélise la propagation par des rayons rectilignes.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.quatrieme,code:"quatrieme",unitOrder:3,title:'Courant alternatif et sécurité',lessonId:'core_pct_4e_ac_safety',lessonTitle:'Le courant alternatif et la sécurité électrique',summary:'Distinguer courant continu et alternatif et connaître les protections.',content:'Une pile fournit généralement une tension continue. Le réseau domestique fournit une tension alternative dangereuse. Un transformateur peut modifier une tension alternative. La prise de terre et les dispositifs de protection contribuent à la sécurité. Ne manipule jamais une prise, un fil secteur ou un appareil ouvert : ces notions s’étudient par schémas et démonstrations encadrées.',keyPoints:['Pile : courant continu','Réseau : courant alternatif','Ne jamais manipuler le secteur','Prise de terre : protection'],exercises:[
    Exercise(id:'core_pct_4e_ac1',lessonId:'core_pct_4e_ac_safety',question:'Quelle source fournit généralement du courant continu ?',options:['Une pile','Une prise domestique','Un transformateur seul'],correctIndex:0,explanation:'Une pile fournit une tension continue.'),
    Exercise(id:'core_pct_4e_ac2',lessonId:'core_pct_4e_ac_safety',question:'Pourquoi ne faut-il pas toucher une prise électrique ?',options:['Le secteur peut provoquer une électrocution','La prise ne contient aucune énergie','Le plastique est toujours conducteur'],correctIndex:0,explanation:'Le courant du secteur est dangereux et peut être mortel.'),
    Exercise(id:'core_pct_4e_ac3',lessonId:'core_pct_4e_ac_safety',question:'Quel dispositif contribue à protéger les personnes ?',options:['La mise à la terre','Un fil dénudé','Un court-circuit'],correctIndex:0,explanation:'La mise à la terre participe à la protection électrique.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.troisieme,code:"troisieme",unitOrder:2,title:'Poids, masse et forces',lessonId:'core_pct_3e_weight_forces',lessonTitle:'Relier le poids à la masse et représenter une force',summary:'Utiliser P = m × g et caractériser une force.',content:'La masse m mesure la quantité de matière et s’exprime en kilogrammes. Le poids P est une force due à la gravité et s’exprime en newtons. Près de la surface terrestre, P = m × g avec g ≈ 10 N/kg pour les exercices usuels. Une force se caractérise par son point d’application, sa direction, son sens et son intensité. On la représente par une flèche.',keyPoints:['Masse : kg ; poids : N','P = m × g','Une force se représente par un vecteur'],exercises:[
    Exercise(id:'core_pct_3e_wf1',lessonId:'core_pct_3e_weight_forces',question:'Quel est le poids approximatif d’une masse de 3 kg avec g = 10 N/kg ?',options:['3 N','30 N','300 N'],correctIndex:1,explanation:'P = m × g = 3 × 10 = 30 N.'),
    Exercise(id:'core_pct_3e_wf2',lessonId:'core_pct_3e_weight_forces',question:'Quelle unité mesure le poids ?',options:['Newton','Kilogramme','Litre'],correctIndex:0,explanation:'Le poids est une force exprimée en newtons.'),
    Exercise(id:'core_pct_3e_wf3',lessonId:'core_pct_3e_weight_forces',question:'Une force se représente par…',options:['Une flèche orientée','Un cercle sans direction','Une couleur uniquement'],correctIndex:0,explanation:'Le vecteur force indique direction, sens et intensité.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.troisieme,code:"troisieme",unitOrder:3,title:'Travail, puissance et machines simples',lessonId:'core_pct_3e_work_machines',lessonTitle:'Calculer le travail et comprendre les machines simples',summary:'Découvrir le travail d’une force, la puissance et le rôle des poulies/leviers.',content:'Le travail mécanique d’une force constante dans la direction du déplacement se calcule W = F × d et s’exprime en joules (J). La puissance indique la rapidité avec laquelle un travail est effectué : P = W/t, en watts (W). Les machines simples comme la poulie, le levier et le plan incliné facilitent certaines tâches en modifiant l’intensité ou la direction de l’effort.',keyPoints:['Travail : W = F × d','Puissance : P = W/t','Poulies et leviers modifient l’effort'],exercises:[
    Exercise(id:'core_pct_3e_wm1',lessonId:'core_pct_3e_work_machines',question:'Une force de 10 N déplace un objet de 2 m dans sa direction. Quel travail ?',options:['5 J','20 J','12 J'],correctIndex:1,explanation:'W = F × d = 10 × 2 = 20 J.'),
    Exercise(id:'core_pct_3e_wm2',lessonId:'core_pct_3e_work_machines',question:'La puissance est le travail effectué…',options:['Par unité de temps','Par unité de masse','Sans temps'],correctIndex:0,explanation:'P = W/t : la puissance est le travail par unité de temps.'),
    Exercise(id:'core_pct_3e_wm3',lessonId:'core_pct_3e_work_machines',question:'Quel appareil est une machine simple ?',options:['Une poulie','Un thermomètre','Une éprouvette'],correctIndex:0,explanation:'La poulie est une machine simple.'),
  ]),
  AnnualPhysicsUnit(level:SchoolLevel.troisieme,code:"troisieme",unitOrder:4,title:'Atomes, ions et réactions chimiques',lessonId:'core_pct_3e_ions_reactions',lessonTitle:'Comprendre les ions et la conservation en réaction',summary:'Décrire atomes, ions et transformations chimiques avec prudence.',content:'Un atome est électriquement neutre. Un ion est un atome ou groupe d’atomes qui a gagné ou perdu des électrons : un cation est positif et un anion négatif. Lors d’une réaction chimique, les atomes se réorganisent ; ils ne sont ni créés ni détruits. On écrit un bilan en conservant le nombre d’atomes de chaque élément. Les expériences chimiques ne sont réalisées qu’en laboratoire avec l’enseignant et les protections adaptées.',keyPoints:['Atome : neutre','Cation : charge positive ; anion : négative','Les atomes se conservent dans une réaction','Expériences chimiques sous supervision'],exercises:[
    Exercise(id:'core_pct_3e_ir1',lessonId:'core_pct_3e_ions_reactions',question:'Un ion positif est appelé…',options:['Cation','Anion','Molécule neutre'],correctIndex:0,explanation:'Un cation porte une charge positive.'),
    Exercise(id:'core_pct_3e_ir2',lessonId:'core_pct_3e_ions_reactions',question:'Lors d’une réaction chimique, les atomes…',options:['Se réorganisent et se conservent','Disparaissent tous','Se transforment en énergie seulement'],correctIndex:0,explanation:'Les atomes sont conservés et se réarrangent.'),
    Exercise(id:'core_pct_3e_ir3',lessonId:'core_pct_3e_ions_reactions',question:'Qui doit encadrer les expériences de chimie ?',options:['L’enseignant avec les protections adaptées','Personne','Un élève seul à la maison'],correctIndex:0,explanation:'Les expériences chimiques nécessitent un encadrement et des règles de sécurité.'),
  ]),
  AnnualPhysicsUnit(level: SchoolLevel.troisieme,code:"troisieme",unitOrder:5,title:'Puissance et énergie électrique',lessonId:'core_pct_3e_electric_power',lessonTitle:'Calculer puissance et énergie électrique',summary:'Relier tension, intensité, puissance et durée dans un circuit simple.',content:'La puissance électrique d’un appareil peut se calculer par P = U × I lorsque les grandeurs sont exprimées en volts et ampères ; la puissance s’exprime en watts. L’énergie consommée est E = P × t, avec une durée en secondes pour obtenir des joules, ou en heures pour des wattheures. Respecte les consignes de sécurité : le secteur domestique est dangereux et ne doit jamais être manipulé par un élève.',keyPoints:['P = U × I, en watts','E = P × t','Ne jamais manipuler le secteur domestique'],exercises:[
    Exercise(id:'core_pct_3e_ep1',lessonId:'core_pct_3e_electric_power',question:'Un appareil fonctionne sous 12 V avec 2 A. Sa puissance est…',options:['24 W','6 W','14 W'],correctIndex:0,explanation:'P = U × I = 12 × 2 = 24 W.'),
    Exercise(id:'core_pct_3e_ep2',lessonId:'core_pct_3e_electric_power',question:'L’énergie consommée dépend de…',options:['La puissance et la durée','La couleur de l’appareil','La longueur du câble uniquement'],correctIndex:0,explanation:'E = P × t : l’énergie dépend de la puissance et du temps de fonctionnement.'),
    Exercise(id:'core_pct_3e_ep3',lessonId:'core_pct_3e_electric_power',question:'Quelle unité mesure la puissance ?',options:['Watt','Joule par kilogramme uniquement','Litre'],correctIndex:0,explanation:'La puissance électrique s’exprime en watts (W).'),
  ]),
  AnnualPhysicsUnit(level: SchoolLevel.troisieme,code:"troisieme",unitOrder:6,title:'Acides, bases et mesure du pH',lessonId:'core_pct_3e_ph',lessonTitle:'Classer des solutions selon leur pH',summary:'Lire une échelle de pH et appliquer les règles de sécurité en chimie.',content:'Le pH indique si une solution aqueuse est acide, neutre ou basique. À température usuelle, pH inférieur à 7 : solution acide ; pH égal à 7 : neutre ; pH supérieur à 7 : basique. Un indicateur coloré ou un pH-mètre permet d’estimer le pH. Ne goûte jamais une solution et ne mélange jamais des produits chimiques sans l’enseignant et les protections adaptées.',keyPoints:['pH < 7 : acide ; pH = 7 : neutre ; pH > 7 : basique','Mesurer avec un indicateur adapté ou un pH-mètre','Ne jamais goûter ni mélanger des produits inconnus'],exercises:[
    Exercise(id:'core_pct_3e_ph1',lessonId:'core_pct_3e_ph',question:'Une solution de pH 3 est…',options:['Acide','Neutre','Basique'],correctIndex:0,explanation:'Un pH inférieur à 7 indique une solution acide.'),
    Exercise(id:'core_pct_3e_ph2',lessonId:'core_pct_3e_ph',question:'Une solution de pH 7 est…',options:['Neutre','Acide','Basique'],correctIndex:0,explanation:'À température usuelle, pH 7 correspond à la neutralité.'),
    Exercise(id:'core_pct_3e_ph3',lessonId:'core_pct_3e_ph',question:'Que faire avec une solution inconnue ?',options:['Ne pas la goûter et suivre les consignes de sécurité','La goûter pour la tester','La mélanger à un autre produit'],correctIndex:0,explanation:'Les produits chimiques inconnus ne doivent jamais être goûtés ou mélangés sans encadrement.'),
  ]),
];

final annualPhysicsSubjects = [
  Subject(id:'core_pct_sixieme',name:'Physique-Chimie et Technologie — cours de l’année',iconName:'science',colorHex:'006A4E',level:SchoolLevel.sixieme,totalChapters:3),
  Subject(id:'core_pct_cinquieme',name:'Physique-Chimie et Technologie — cours de l’année',iconName:'science',colorHex:'006A4E',level:SchoolLevel.cinquieme,totalChapters:3),
  Subject(id:'core_pct_quatrieme',name:'Physique-Chimie et Technologie — cours de l’année',iconName:'science',colorHex:'006A4E',level:SchoolLevel.quatrieme,totalChapters:3),
];

final annualPhysicsChapters = annualPhysicsUnits.map((unit) => Chapter(
  id:unit.chapterId,subjectId:unit.subjectId,title:'Unité ${unit.unitOrder} — ${unit.title}',
  order:unit.unitOrder,term:unit.unitOrder,totalLessons:1,
)).toList();

final annualPhysicsLessons = annualPhysicsUnits.map((unit) => Lesson(
  id:unit.lessonId,chapterId:unit.chapterId,title:unit.lessonTitle,
  summary:unit.summary,content:unit.content,keyPoints:unit.keyPoints,durationMinutes:25,
)).toList();

final annualPhysicsExercises = annualPhysicsUnits.expand((unit)=>unit.exercises).toList();
